mapper.select:
select m.`park_org_id`, m.`meter_no`, m.`category`, m.`effect_property`, m.`effect_type`, m.`meter_type`, m.`name`, m.`serial_number`, mr.`id` id, mr.`meter_id`, mr.`meter_reading`, mr.reading_time, mr.`corrected_reading`, mr.`remark` from dev_meter m inner join (SELECT id,meter_id,meter_reading,corrected_reading,year,month,day,reading_time,remark,deleted FROM dev_meter_reading_record a WHERE a.reading_time=(SELECT max(b.reading_time) FROM dev_meter_reading_record b WHERE a.meter_id=b.meter_id and a.year=b.year and a.day=b.day and a.`month`=b.`month` )) as mr on m.id=mr.meter_id
m.deleted=0 and mr.deleted=0
and m.park_org_id=#{q.parkOrgId}
and m.category=#{q.category}
and m.name like concat('%',#{q.name},'%')
and m.serial_umber=#{q.serialNumber}
and m.meter_type=#{q.meterType}
and m.reading_time >= #{q.readingTimeStart} and m.reading_time <= #{q.readingTimeEnd}
and m.park_org_id in
#{parkOrgId}
order by mr.reading_time desc

select m.`park_org_id`, m.`building_id`, m.`floors`, m.`house_ids`, m.`meter_no`, m.`category`, m.`effect_property`, m.`effect_type`, m.`meter_type`, m.`name`, m.`serial_number`, m.floors, mr.`id` id, mr.`meter_id`, mr.`year` thisYear, mr.`month` thisMonth, mr.meter_reading, mr.reading_time thisPeriodTime, mr.`corrected_reading` thisReading from dev_meter m inner join (SELECT id,meter_id,meter_reading,corrected_reading,year,month,day,reading_time,remark,deleted FROM dev_meter_reading_record a WHERE a.reading_time=(SELECT max(b.reading_time) FROM dev_meter_reading_record b WHERE a.meter_id=b.meter_id and a.year=b.year and a.`month`=b.`month` )) as mr on m.id=mr.meter_id
m.deleted=0 and mr.deleted=0
and m.park_org_id=#{q.parkOrgId}
and m.category=#{q.category}
and m.building_id=#{q.buildingId}
and json_contains(m.floors,#{q.floor})
and json_contains(m.house_ids,concat('"',#{q.houseId},'"'))
and m.name like concat('%',#{q.name},'%')
and m.serial_umber=#{q.serialNumber}
and mr.year=#{q.year}
and mr.month=#{q.month}
and m.park_org_id in
#{parkOrgId}
and mr.meter_id in
#{meterId}
order by mr.reading_time desc

SELECT *
FROM dev_meter_reading_record a
WHERE a.reading_time = (SELECT max(reading_time)
FROM dev_meter_reading_record b
WHERE a.meter_id = b.meter_id

    and b.reading_time > #{start}


    and b.reading_time < #{end}


    and b.meter_id in

        #{meterId}


GROUP BY b.meter_id
)

SELECT *
FROM dev_meter_reading_record a
WHERE a.reading_time = (SELECT min(reading_time)
FROM dev_meter_reading_record b
WHERE a.meter_id = b.meter_id

    and b.reading_time > #{start}


    and b.reading_time < #{end}


    and b.meter_id in

        #{meterId}


GROUP BY b.meter_id
)
